macro_rules! impl_17 {
    () => {
        deps!();
        impl Stream { # [doc = " Initialize .xz stream encoder using a preset number"] # [doc = ""] # [doc = " This is intended to be used by most for encoding data. The `preset`"] # [doc = " argument is a number 0-9 indicating the compression level to use, and"] # [doc = " normally 6 is a reasonable default."] # [doc = ""] # [doc = " The `check` argument is the integrity check to insert at the end of the"] # [doc = " stream. The default of `Crc64` is typically appropriate."] pub fn new_easy_encoder (preset : u32 , check : Check) -> Result < Stream , Error > { unsafe { let mut init = Stream { raw : mem :: zeroed () } ; cvt (lzma_sys :: lzma_easy_encoder (& mut init . raw , preset , check as lzma_sys :: lzma_check ,)) ? ; Ok (init) } } # [doc = " Initialize .lzma encoder (legacy file format)"] # [doc = ""] # [doc = " The .lzma format is sometimes called the LZMA_Alone format, which is the"] # [doc = " reason for the name of this function. The .lzma format supports only the"] # [doc = " LZMA1 filter. There is no support for integrity checks like CRC32."] # [doc = ""] # [doc = " Use this function if and only if you need to create files readable by"] # [doc = " legacy LZMA tools such as LZMA Utils 4.32.x. Moving to the .xz format"] # [doc = " (the `new_easy_encoder` function) is strongly recommended."] # [doc = ""] # [doc = " The valid action values for `process` are `Run` and `Finish`. No kind"] # [doc = " of flushing is supported, because the file format doesn't make it"] # [doc = " possible."] pub fn new_lzma_encoder (options : & LzmaOptions) -> Result < Stream , Error > { unsafe { let mut init = Stream { raw : mem :: zeroed () } ; cvt (lzma_sys :: lzma_alone_encoder (& mut init . raw , & options . raw)) ? ; Ok (init) } } # [doc = " Initialize .xz Stream encoder using a custom filter chain"] # [doc = ""] # [doc = " This function is similar to `new_easy_encoder` but a custom filter chain"] # [doc = " is specified."] pub fn new_stream_encoder (filters : & Filters , check : Check) -> Result < Stream , Error > { unsafe { let mut init = Stream { raw : mem :: zeroed () } ; cvt (lzma_sys :: lzma_stream_encoder (& mut init . raw , filters . inner . as_ptr () , check as lzma_sys :: lzma_check ,)) ? ; Ok (init) } } # [doc = " Initialize a .xz stream decoder."] # [doc = ""] # [doc = " The maximum memory usage can be specified along with flags such as"] # [doc = " `TELL_ANY_CHECK`, `TELL_NO_CHECK`, `TELL_UNSUPPORTED_CHECK`,"] # [doc = " `TELL_IGNORE_CHECK`, or `CONCATENATED`."] pub fn new_stream_decoder (memlimit : u64 , flags : u32) -> Result < Stream , Error > { unsafe { let mut init = Stream { raw : mem :: zeroed () } ; cvt (lzma_sys :: lzma_stream_decoder (& mut init . raw , memlimit , flags ,)) ? ; Ok (init) } } # [doc = " Initialize a .lzma stream decoder."] # [doc = ""] # [doc = " The maximum memory usage can also be specified."] pub fn new_lzma_decoder (memlimit : u64) -> Result < Stream , Error > { unsafe { let mut init = Stream { raw : mem :: zeroed () } ; cvt (lzma_sys :: lzma_alone_decoder (& mut init . raw , memlimit)) ? ; Ok (init) } } # [doc = " Initialize a decoder which will choose a stream/lzma formats depending"] # [doc = " on the input stream."] pub fn new_auto_decoder (memlimit : u64 , flags : u32) -> Result < Stream , Error > { unsafe { let mut init = Stream { raw : mem :: zeroed () } ; cvt (lzma_sys :: lzma_auto_decoder (& mut init . raw , memlimit , flags)) ? ; Ok (init) } } # [doc = " Processes some data from input into an output buffer."] # [doc = ""] # [doc = " This will perform the appropriate encoding or decoding operation"] # [doc = " depending on the kind of underlying stream. Documentation for the"] # [doc = " various `action` arguments can be found on the respective variants."] pub fn process (& mut self , input : & [u8] , output : & mut [u8] , action : Action ,) -> Result < Status , Error > { self . raw . next_in = input . as_ptr () ; self . raw . avail_in = input . len () ; self . raw . next_out = output . as_mut_ptr () ; self . raw . avail_out = output . len () ; let action = action as lzma_sys :: lzma_action ; unsafe { cvt (lzma_sys :: lzma_code (& mut self . raw , action)) } } # [doc = " Performs the same data as `process`, but places output data in a `Vec`."] # [doc = ""] # [doc = " This function will use the extra capacity of `output` as a destination"] # [doc = " for bytes to be placed. The length of `output` will automatically get"] # [doc = " updated after the operation has completed."] pub fn process_vec (& mut self , input : & [u8] , output : & mut Vec < u8 > , action : Action ,) -> Result < Status , Error > { let cap = output . capacity () ; let len = output . len () ; unsafe { let before = self . total_out () ; let ret = { let ptr = output . as_mut_ptr () . offset (len as isize) ; let out = slice :: from_raw_parts_mut (ptr , cap - len) ; self . process (input , out , action) } ; output . set_len ((self . total_out () - before) as usize + len) ; return ret ; } } # [doc = " Returns the total amount of input bytes consumed by this stream."] pub fn total_in (& self) -> u64 { self . raw . total_in } # [doc = " Returns the total amount of bytes produced by this stream."] pub fn total_out (& self) -> u64 { self . raw . total_out } # [doc = " Get the current memory usage limit."] # [doc = ""] # [doc = " This is only supported if the underlying stream supports a memlimit."] pub fn memlimit (& self) -> u64 { unsafe { lzma_sys :: lzma_memlimit_get (& self . raw) } } # [doc = " Set the current memory usage limit."] # [doc = ""] # [doc = " This can return `Error::MemLimit` if the new limit is too small or"] # [doc = " `Error::Program` if this stream doesn't take a memory limit."] pub fn set_memlimit (& mut self , limit : u64) -> Result < () , Error > { cvt (unsafe { lzma_sys :: lzma_memlimit_set (& mut self . raw , limit) }) . map (| _ | ()) } }
    };
}

